using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Interface;
using SolutionOne_Core.CanteenManagementModels.MealSession;

namespace SolutionOneWebPortal_API.Controllers.Canteen_Management;

[Authorize]
[Route("api/[controller]")]
[ApiController]
public class MealSessionController : ControllerBase
{
    private readonly IMealSessionService _service;

    public MealSessionController(IMealSessionService service)
    {
        _service = service;
    }

    [HttpGet("GetAllMealSessions")]
    public async Task<IActionResult> GetAllMealSessions()
    {
        var (response, data) = await _service.GetAllMealSessionsAsync();
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }

    [HttpGet("GetAllSessionNames")]
    public async Task<IActionResult> GetAllSessionNames()
    {
        var (response, data) = await _service.GetAllSessionNamesAsync();
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }

    [HttpGet("GetMealSessionById/{id:int}")]
    public async Task<IActionResult> GetMealSessionById(int id)
    {
        var (response, data) = await _service.GetMealSessionByIdAsync(id);
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }

    [HttpGet("GetEmployeeMealRates/{employeeMasterId:long}")]
    public async Task<IActionResult> GetEmployeeMealRates(long employeeMasterId)
    {
        var (response, data) = await _service.GetEmployeeMealRatesAsync(employeeMasterId);
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }

    [HttpPost("InsertMealSession")]
    public async Task<IActionResult> InsertMealSession([FromBody] MealSessionSaveModel model)
    {
        var response = await _service.InsertMealSessionAsync(model);
        return StatusCode((int)response.Status, response);
    }

    [HttpPost("UpdateMealSession")]
    public async Task<IActionResult> UpdateMealSession([FromBody] MealSessionSaveModel model)
    {
        var response = await _service.UpdateMealSessionAsync(model);
        return StatusCode((int)response.Status, response);
    }

    [HttpPost("DeleteMealSession/{id:int}")]
    public async Task<IActionResult> DeleteMealSession(int id)
    {
        var response = await _service.DeleteMealSessionAsync(id);
        return StatusCode((int)response.Status, response);
    }
}

