    public int MSessionId { get; set; }
    public int SessionNameId { get; set; }
    public string SessionName { get; set; } = string.Empty;
    public string StartTime { get; set; } = string.Empty;
    public string EndTime { get; set; } = string.Empty;
    public string CanteenFacilityType { get; set; } = string.Empty;
    public decimal CompanyShare { get; set; }
    public decimal EmployeeShare { get; set; }
    public decimal TotalRate => CompanyShare + EmployeeShare;
}
=== SQL SCRIPT (rates) ===
/*
    Update: Canteen meal session rates - Daily and Adhoc
    Date: 2026-10-22

    HOW THE RATES WORK
      Every meal session (Breakfast, Lunch ...) carries TWO rates, each split into a company part and an employee part:
        Daily  rate   CompanyShare      + EmployeeShare        for employees whose Meal Plan is "Daily Meal"
        Adhoc  rate   AdhocCompanyShare + AdhocEmployeeShare   for employees whose Meal Plan is "Adhoc Meal"
      The employee's plan lives on HR_EmployeeMaster.CanteenFacilityType; the application picks the matching pair
      (GET api/MealSession/GetEmployeeMealRates/{employeeMasterId}).
      Migration_CanteenDailyAdhocRates_20261016.sql copied each session's Daily shares into its Adhoc shares, so right now
      Daily = Adhoc everywhere. This script is how you give the Adhoc plan its own rate.

    HOW TO USE
      1. Run it as it is. It changes nothing: it lists every meal session with its current and new rates.
      2. Fill in your rates in the EDIT HERE block (one UPDATE line per session). A column left out stays as it is.
      3. Run it again and check the "new" columns, then set @Apply = 1 and run it a last time to save.

    IF THE ADHOC RATES ARE ALL 0
      Rows loaded later (e.g. DbMigrator/deploy/module_data/01_canteen.sql, which only carries CompanyShare / EmployeeShare) get 0 in
      the Adhoc columns, because the migration's copy of Daily into Adhoc only ran once, when the columns were added. Set
      @CopyDailyToAdhocWhereZero = 1 to give every session whose Adhoc rate is 0 + 0 the same rate as its Daily one (what the
      migration intended: nothing changes for anyone until HR edits the Adhoc rate). A rate you type below always wins.

    Run Migration_CanteenDailyAdhocRates_20261016.sql first (it adds the Adhoc columns). Safe to run more than once.
    SQL Server 2014 compatible.
*/

SET NOCOUNT ON;

DECLARE @Apply        BIT    = 0;   -- 0 = preview only (default), 1 = save the changes
DECLARE @ModifiedById BIGINT = 1;   -- written to HR_CMS_MealSession.ModifiedById
DECLARE @CopyDailyToAdhocWhereZero BIT = 0;   -- 1 = a session whose Adhoc rate is 0 + 0 gets its Daily rate as the Adhoc rate

-- One row per session name, filled in by you below. (COLLATE DATABASE_DEFAULT: a temp table otherwise takes tempdb's collation,
-- which can differ from this database's and makes every comparison with a real column fail with error 468.) NULL = keep the current value. Pre-filled with the real session names,
-- so a mistyped name can never be the reason an update did nothing.
IF OBJECT_ID('tempdb..#Rates') IS NOT NULL DROP TABLE #Rates;
CREATE TABLE #Rates
(
    SessionName   NVARCHAR(50)  COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
    DailyCompany  DECIMAL(10,2) NULL,
    DailyEmployee DECIMAL(10,2) NULL,
    AdhocCompany  DECIMAL(10,2) NULL,
    AdhocEmployee DECIMAL(10,2) NULL
);

IF OBJECT_ID(N'[dbo].[HR_CMS_SessionName]', N'U') IS NULL OR OBJECT_ID(N'[dbo].[HR_CMS_MealSession]', N'U') IS NULL
BEGIN
    RAISERROR(N'HR_CMS_SessionName / HR_CMS_MealSession do not exist in this database.', 16, 1);
    RETURN;
END

IF COL_LENGTH('dbo.HR_CMS_MealSession', 'AdhocCompanyShare') IS NULL OR COL_LENGTH('dbo.HR_CMS_MealSession', 'AdhocEmployeeShare') IS NULL
BEGIN
    RAISERROR(N'The Adhoc columns are missing. Run Migration_CanteenDailyAdhocRates_20261016.sql first.', 16, 1);
    RETURN;
END

INSERT INTO #Rates (SessionName) SELECT SessionName FROM dbo.HR_CMS_SessionName;

/* ========================== EDIT HERE ==========================================================================
   One line per session. Each amount is rupees per meal. Delete the leading -- and put your own figures in.
   Examples (illustration only - these are NOT recommended figures):

   -- Daily regular eaters: company pays 30, employee pays 20 (total 50).
   -- Adhoc occasional eaters: company pays 10, employee pays 60 (total 70).
   -- UPDATE #Rates SET DailyCompany = 30.00, DailyEmployee = 20.00, AdhocCompany = 10.00, AdhocEmployee = 60.00 WHERE SessionName = N'Lunch';

   -- Change only the Adhoc rate and leave the Daily one alone:
   -- UPDATE #Rates SET AdhocCompany = 0.00, AdhocEmployee = 40.00 WHERE SessionName = N'Breakfast';

   -- The Daily rates in the testers' backup (hrms_21102026.bak -> 01_canteen.sql), if the Daily ones here are 0 as well.
   -- Adhoc is set equal to Daily, as the migration intended; change the Adhoc figures when HR decides them:
   -- UPDATE #Rates SET DailyCompany = 20.00, DailyEmployee = 10.00, AdhocCompany = 20.00, AdhocEmployee = 10.00 WHERE SessionName = N'Breakfast';
   -- UPDATE #Rates SET DailyCompany = 60.00, DailyEmployee = 20.00, AdhocCompany = 60.00, AdhocEmployee = 20.00 WHERE SessionName = N'Lunch';
   -- UPDATE #Rates SET DailyCompany = 15.00, DailyEmployee =  5.00, AdhocCompany = 15.00, AdhocEmployee =  5.00 WHERE SessionName = N'Evening Snacks';
   -- UPDATE #Rates SET DailyCompany = 60.00, DailyEmployee = 20.00, AdhocCompany = 60.00, AdhocEmployee = 20.00 WHERE SessionName = N'Dinner';
   ================================================================================================================ */



-- ---------------------------------------------------------------------------------------------------------------------
-- Nothing below needs editing.
-- (Dynamic SQL, so a database that has not had the Adhoc migration yet gets the message above instead of a compile error.)
-- ---------------------------------------------------------------------------------------------------------------------
DECLARE @sql NVARCHAR(MAX) = N'
-- Optional: where a session''s Adhoc rate is 0 + 0, use its Daily rate (a rate typed above is never replaced).
IF @CopyDailyToAdhocWhereZero = 1
    UPDATE r
       SET r.AdhocCompany  = ISNULL(r.AdhocCompany,  ISNULL(r.DailyCompany,  ms.CompanyShare)),
           r.AdhocEmployee = ISNULL(r.AdhocEmployee, ISNULL(r.DailyEmployee, ms.EmployeeShare))
    FROM #Rates r
    INNER JOIN dbo.HR_CMS_SessionName n ON n.SessionName COLLATE DATABASE_DEFAULT = r.SessionName
    INNER JOIN dbo.HR_CMS_MealSession ms ON ms.SessionNameId = n.SessionNameId
    WHERE ms.AdhocCompanyShare = 0 AND ms.AdhocEmployeeShare = 0;

IF EXISTS (SELECT 1 FROM #Rates WHERE DailyCompany < 0 OR DailyEmployee < 0 OR AdhocCompany < 0 OR AdhocEmployee < 0)
BEGIN
    RAISERROR(N''Rates cannot be negative.'', 16, 1);
    RETURN;
END

-- 1. What each meal session has now, what it will have, and whether anything changes.
SELECT n.SessionName,
       ms.IsActive,
       [Daily co. now]   = ms.CompanyShare,
       [Daily emp. now]  = ms.EmployeeShare,
       [Daily co. new]   = ISNULL(r.DailyCompany,  ms.CompanyShare),
       [Daily emp. new]  = ISNULL(r.DailyEmployee, ms.EmployeeShare),
       [Daily total new] = ISNULL(r.DailyCompany,  ms.CompanyShare)      + ISNULL(r.DailyEmployee,  ms.EmployeeShare),
       [Adhoc co. now]   = ms.AdhocCompanyShare,
       [Adhoc emp. now]  = ms.AdhocEmployeeShare,
       [Adhoc co. new]   = ISNULL(r.AdhocCompany,  ms.AdhocCompanyShare),
       [Adhoc emp. new]  = ISNULL(r.AdhocEmployee, ms.AdhocEmployeeShare),
       [Adhoc total new] = ISNULL(r.AdhocCompany,  ms.AdhocCompanyShare) + ISNULL(r.AdhocEmployee, ms.AdhocEmployeeShare),
       [Result] = CASE WHEN ISNULL(r.DailyCompany,  ms.CompanyShare)       = ms.CompanyShare
                        AND ISNULL(r.DailyEmployee, ms.EmployeeShare)      = ms.EmployeeShare
                        AND ISNULL(r.AdhocCompany,  ms.AdhocCompanyShare)  = ms.AdhocCompanyShare
                        AND ISNULL(r.AdhocEmployee, ms.AdhocEmployeeShare) = ms.AdhocEmployeeShare
                       THEN N''no change'' ELSE N''WILL CHANGE'' END
FROM dbo.HR_CMS_MealSession ms
INNER JOIN dbo.HR_CMS_SessionName n ON n.SessionNameId = ms.SessionNameId
LEFT  JOIN #Rates r ON r.SessionName = n.SessionName COLLATE DATABASE_DEFAULT
ORDER BY n.SortOrder, n.SessionName;

-- 2. Session names you gave rates for that have no meal session row yet (add it on the Meal Session screen first).
SELECT r.SessionName AS [Has rates above but no meal session row - nothing to update]
FROM #Rates r
WHERE (r.DailyCompany IS NOT NULL OR r.DailyEmployee IS NOT NULL OR r.AdhocCompany IS NOT NULL OR r.AdhocEmployee IS NOT NULL)
  AND NOT EXISTS (SELECT 1 FROM dbo.HR_CMS_MealSession ms INNER JOIN dbo.HR_CMS_SessionName n ON n.SessionNameId = ms.SessionNameId WHERE n.SessionName COLLATE DATABASE_DEFAULT = r.SessionName);

IF @Apply = 1
BEGIN
    BEGIN TRAN;

    UPDATE ms
       SET ms.CompanyShare       = ISNULL(r.DailyCompany,  ms.CompanyShare),
           ms.EmployeeShare      = ISNULL(r.DailyEmployee, ms.EmployeeShare),
           ms.AdhocCompanyShare  = ISNULL(r.AdhocCompany,  ms.AdhocCompanyShare),
           ms.AdhocEmployeeShare = ISNULL(r.AdhocEmployee, ms.AdhocEmployeeShare),
           ms.ModifiedDate       = GETDATE(),
           ms.ModifiedById       = @ModifiedById
    FROM dbo.HR_CMS_MealSession ms
    INNER JOIN dbo.HR_CMS_SessionName n ON n.SessionNameId = ms.SessionNameId
    INNER JOIN #Rates r ON r.SessionName = n.SessionName COLLATE DATABASE_DEFAULT
    WHERE ISNULL(r.DailyCompany,  ms.CompanyShare)       <> ms.CompanyShare
       OR ISNULL(r.DailyEmployee, ms.EmployeeShare)      <> ms.EmployeeShare
       OR ISNULL(r.AdhocCompany,  ms.AdhocCompanyShare)  <> ms.AdhocCompanyShare
       OR ISNULL(r.AdhocEmployee, ms.AdhocEmployeeShare) <> ms.AdhocEmployeeShare;

    DECLARE @updated INT = @@ROWCOUNT;
    COMMIT;

    SELECT @updated AS [Meal sessions updated];

    -- 3. The rates as they are now.
    SELECT n.SessionName, ms.CompanyShare AS [Daily co.], ms.EmployeeShare AS [Daily emp.], ms.CompanyShare + ms.EmployeeShare AS [Daily total],
           ms.AdhocCompanyShare AS [Adhoc co.], ms.AdhocEmployeeShare AS [Adhoc emp.], ms.AdhocCompanyShare + ms.AdhocEmployeeShare AS [Adhoc total]
    FROM dbo.HR_CMS_MealSession ms
    INNER JOIN dbo.HR_CMS_SessionName n ON n.SessionNameId = ms.SessionNameId
    ORDER BY n.SortOrder, n.SessionName;
END
ELSE
    PRINT N''Preview only - nothing was changed. Set @Apply = 1 to save.'';
';

EXEC sp_executesql @sql, N'@Apply BIT, @ModifiedById BIGINT, @CopyDailyToAdhocWhereZero BIT',
     @Apply = @Apply, @ModifiedById = @ModifiedById, @CopyDailyToAdhocWhereZero = @CopyDailyToAdhocWhereZero;

