=== FORM TS ===
import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { AbstractControl, FormBuilder, FormGroup, ReactiveFormsModule, ValidationErrors, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import {
  DxButtonModule,
  DxCheckBoxModule,
  DxNumberBoxModule,
  DxSelectBoxModule,
  DxTextBoxModule,
} from 'devextreme-angular';
import { forkJoin } from 'rxjs';
import { finalize } from 'rxjs/operators';
import { ApiService } from '../../../../services/api.service';
import { AuthService } from '../../../../services/auth.service';
import { ChipNavigationService } from '../../../../services/ChipNavigation.service';
import { ToastService } from '../../../../services/toaster.service';

@Component({
  selector: 'app-meal-session-form',
  standalone: true,
  host: { class: 'is-form-page' },
  imports: [
    CommonModule,
    ReactiveFormsModule,
    DxSelectBoxModule,
    DxTextBoxModule,
    DxNumberBoxModule,
    DxCheckBoxModule,
    DxButtonModule,
  ],
  templateUrl: './meal-session-form.component.html',
  styleUrls: ['./meal-session-form.component.scss'],
})
export class MealSessionFormComponent implements OnInit {
  mealSessionForm!: FormGroup;
  sessionNames: { id: number; name: string }[] = [];
  private allSessionNames: { id: number; name: string }[] = [];
  private usedSessionNameIds = new Set<number>();
  isLoading = false;
  isSaving = false;
  formSubmitted = false;
  isAddMode = true;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private route: ActivatedRoute,
    private api: ApiService,
    private toast: ToastService,
    private chipService: ChipNavigationService,
    private authService: AuthService,
  ) {
    this.mealSessionForm = this.fb.group({
      mSessionId: [0],
      sessionNameId: [null, Validators.required],
      startTime: ['', [Validators.required, MealSessionFormComponent.timeValidator]],
      endTime: ['', [Validators.required, MealSessionFormComponent.timeValidator]],
      companyShare: [0, [Validators.required, Validators.min(0)]],
      employeeShare: [0, [Validators.required, Validators.min(0)]],
      adhocCompanyShare: [0, [Validators.required, Validators.min(0)]],
      adhocEmployeeShare: [0, [Validators.required, Validators.min(0)]],
      isActive: [true],
    });
  }

  ngOnInit(): void {
    this.loadLookupData();

    this.route.paramMap.subscribe((params) => {
      const id = Number(params.get('id') || 0);
      this.isAddMode = id <= 0;

      if (this.isAddMode) {
        this.authService.ScreenName = 'Add Meal Session';
        this.chipService.addTab({
          title: 'Add Meal Session',
          route: '/canteen-management/meal-session/editform',
        });
        this.mealSessionForm.get('sessionNameId')?.enable();
        this.applySessionNamesForAdd();
      } else {
        this.authService.ScreenName = 'Edit Meal Session';
        this.chipService.addTab({
          title: 'Edit Meal Session',
          route: `/canteen-management/meal-session/editform/${id}`,
        });
        this.loadRecord(id);
      }
    });
  }

  get dailyTotal(): number {
    const v = this.mealSessionForm.getRawValue();
    return (Number(v.companyShare) || 0) + (Number(v.employeeShare) || 0);
  }

  get adhocTotal(): number {
    const v = this.mealSessionForm.getRawValue();
    return (Number(v.adhocCompanyShare) || 0) + (Number(v.adhocEmployeeShare) || 0);
  }

  save(): void {
    this.formSubmitted = true;
    if (this.mealSessionForm.invalid) {
      this.toast.warning('Please correct validation errors before saving.');
      return;
    }

    const v = this.mealSessionForm.getRawValue();
    const startTime = this.formatTimeForApi(v.startTime);
    const endTime = this.formatTimeForApi(v.endTime);

    if (startTime >= endTime) {
      this.toast.warning('End time must be after start time.');
      return;
    }

    const isEdit = !this.isAddMode;
    const url = isEdit ? '/api/MealSession/UpdateMealSession' : '/api/MealSession/InsertMealSession';
    const payload = {
      mSessionId: isEdit ? Number(v.mSessionId) : 0,
      sessionNameId: Number(v.sessionNameId),
      startTime,
      endTime,
      companyShare: Number(v.companyShare) || 0,
      employeeShare: Number(v.employeeShare) || 0,
      adhocCompanyShare: Number(v.adhocCompanyShare) || 0,
      adhocEmployeeShare: Number(v.adhocEmployeeShare) || 0,
      isActive: !!v.isActive,
    };

    this.isSaving = true;
    this.api
      .post(url, payload)
      .pipe(finalize(() => (this.isSaving = false)))
      .subscribe({
        next: (res: Record<string, unknown>) => {
          const ok = !!(res['isSuccess'] ?? res['IsSuccess'] ?? res['success']);
          if (!ok) {
            this.toast.error(String(res['message'] ?? 'Save failed.'));
            return;
          }
          this.toast.success(String(res['message'] ?? (isEdit ? 'Meal session updated.' : 'Meal session added.')));
          this.router.navigate(['/canteen-management/meal-session']);
        },
        error: (err: { error?: { message?: string } }) => {
          this.toast.error(err?.error?.message ?? 'Unable to save meal session.');
        },
      });
  }

  cancel(): void {
    this.router.navigate(['/canteen-management/meal-session']);
  }

  hasError(controlName: string, errorCode?: string): boolean {
    const c = this.mealSessionForm.get(controlName);
    if (!c || !this.formSubmitted) return false;
    return errorCode ? c.hasError(errorCode) : c.invalid;
  }

  onTimeInput(controlName: 'startTime' | 'endTime', e: { event?: Event }): void {
    const input = e.event?.target as HTMLInputElement | null;
    if (!input) return;

    const formatted = this.formatTimeInputValue(input.value);
    this.mealSessionForm.get(controlName)?.setValue(formatted, { emitEvent: false });
    input.value = formatted;
  }

  onTimeBlur(controlName: 'startTime' | 'endTime'): void {
    const control = this.mealSessionForm.get(controlName);
    if (!control) return;

    const formatted = this.completeTimeValue(String(control.value ?? ''));
    if (formatted !== control.value) {
      control.setValue(formatted);
    }
  }

  private static timeValidator(control: AbstractControl): ValidationErrors | null {
    const value = String(control.value ?? '').trim();
    if (!value) return null;

    const match = value.match(/^(\d{2}):(\d{2})$/);
    if (!match) return { invalidTime: true };

    const hours = Number(match[1]);
    const minutes = Number(match[2]);
    if (hours > 23 || minutes > 59) return { invalidTime: true };

    return null;
  }

  private loadLookupData(): void {
    forkJoin({
      names: this.api.get('/api/MealSession/GetAllSessionNames'),
      sessions: this.api.get('/api/MealSession/GetAllMealSessions'),
    }).subscribe({
      next: ({ names, sessions }) => {
        this.allSessionNames = this.mapSessionNames(names);
        this.usedSessionNameIds = this.mapUsedSessionNameIds(sessions);
        if (this.isAddMode) {
          this.applySessionNamesForAdd();
        } else {
          const sessionNameId = Number(this.mealSessionForm.get('sessionNameId')?.value ?? 0);
          if (sessionNameId > 0) {
            this.applySessionNamesForEdit(sessionNameId);
          }
        }
      },
      error: () => {
        this.allSessionNames = [];
        this.usedSessionNameIds = new Set();
        this.sessionNames = [];
      },
    });
  }

  private mapSessionNames(res: Record<string, unknown>): { id: number; name: string }[] {
    const raw = (res['data'] ?? res['Data'] ?? []) as Record<string, unknown>[];
    if (!Array.isArray(raw)) return [];

    return raw
      .map((r) => ({
        id: Number(r['sessionNameId'] ?? r['SessionNameId'] ?? 0),
        name: String(r['sessionName'] ?? r['SessionName'] ?? ''),
      }))
      .filter((x) => x.id > 0 && x.name);
  }

  private mapUsedSessionNameIds(res: Record<string, unknown>): Set<number> {
    const raw = (res['data'] ?? res['Data'] ?? []) as Record<string, unknown>[];
    if (!Array.isArray(raw)) return new Set();

    return new Set(
      raw
        .map((r) => Number(r['sessionNameId'] ?? r['SessionNameId'] ?? 0))
        .filter((id) => id > 0),
    );
  }

  private applySessionNamesForAdd(): void {
    this.sessionNames = this.allSessionNames.filter((x) => !this.usedSessionNameIds.has(x.id));
    const currentId = this.mealSessionForm.get('sessionNameId')?.value;
    if (currentId && !this.sessionNames.some((x) => x.id === currentId)) {
      this.mealSessionForm.patchValue({ sessionNameId: null });
    }
  }

  private applySessionNamesForEdit(sessionNameId: number): void {
    this.sessionNames = this.allSessionNames.filter((x) => x.id === sessionNameId);
    this.mealSessionForm.get('sessionNameId')?.disable();
  }

  private loadRecord(id: number): void {
    this.isLoading = true;
    this.api
      .get(`/api/MealSession/GetMealSessionById/${id}`)
      .pipe(finalize(() => (this.isLoading = false)))
      .subscribe({
        next: (res: Record<string, unknown>) => {
          const data = (res['data'] ?? res['Data']) as Record<string, unknown>;
          if (!data || (!data['sessionNameId'] && !data['SessionNameId'] && !data['mSessionId'] && !data['MSessionId'])) {
            this.toast.error('Meal session not found.');
            this.cancel();
            return;
          }

          const sessionNameId = Number(data['sessionNameId'] ?? data['SessionNameId'] ?? 0) || null;
          this.applySessionNamesForEdit(sessionNameId ?? 0);
          this.mealSessionForm.patchValue({
            mSessionId: Number(data['mSessionId'] ?? data['MSessionId'] ?? id),
            sessionNameId,
            startTime: this.toDisplayTime(data['startTime'] ?? data['StartTime']),
            endTime: this.toDisplayTime(data['endTime'] ?? data['EndTime']),
            companyShare: Number(data['companyShare'] ?? data['CompanyShare'] ?? 0),
            employeeShare: Number(data['employeeShare'] ?? data['EmployeeShare'] ?? 0),
            adhocCompanyShare: Number(data['adhocCompanyShare'] ?? data['AdhocCompanyShare'] ?? 0),
            adhocEmployeeShare: Number(data['adhocEmployeeShare'] ?? data['AdhocEmployeeShare'] ?? 0),
            isActive: data['isActive'] ?? data['IsActive'] ?? true,
          });
        },
        error: () => {
          this.toast.error('Failed to load meal session.');
          this.cancel();
        },
      });
  }

  private toDisplayTime(value: unknown): string {
    if (!value) return '';
    const text = String(value);
    const match = text.match(/(\d{1,2}):(\d{2})/);
    if (!match) return '';
    return `${match[1].padStart(2, '0')}:${match[2].padStart(2, '0')}`;
  }

  private formatTimeInputValue(raw: string): string {
    let digits = raw.replace(/\D/g, '').slice(0, 4);
    if (!digits) return '';

    if (digits.length === 1 && Number(digits) > 2) {
      digits = `0${digits}`;
    }

    if (digits.length === 3 && Number(digits[2]) > 5) {
      digits = `${digits.slice(0, 2)}0${digits[2]}`;
    }

    const hourPart = digits.slice(0, 2);
    const minutePart = digits.slice(2, 4);

    if (digits.length <= 2) {
      const hour = hourPart.length === 2 ? String(Math.min(23, Number(hourPart))).padStart(2, '0') : hourPart;
      return hourPart.length === 2 ? `${hour}:` : hour;
    }

    const hour = String(Math.min(23, Number(hourPart))).padStart(2, '0');
    const minute =
      minutePart.length === 2
        ? String(Math.min(59, Number(minutePart))).padStart(2, '0')
        : minutePart;

    return `${hour}:${minute}`;
  }

  private completeTimeValue(value: string): string {
    const digits = value.replace(/\D/g, '').slice(0, 4);
    if (!digits) return '';

    const hour = String(Math.min(23, Number(digits.slice(0, 2).padEnd(2, '0')))).padStart(2, '0');
    const minute = String(Math.min(59, Number(digits.slice(2, 4).padEnd(2, '0')))).padStart(2, '0');
    return `${hour}:${minute}`;
  }

  private formatTimeForApi(value: string | null): string {
    const text = String(value ?? '').trim();
    const match = text.match(/^(\d{2}):(\d{2})$/);
    if (!match) return '';
    return `${match[1]}:${match[2]}:00`;
  }
}
=== FORM HTML ===
<form [formGroup]="mealSessionForm" class="meal-session-form meal-session-form-page">
  <div class="page-wrapper meal-session-form-wrap" [class.meal-session-form-wrap--loading]="isLoading">
    <div class="form-card meal-session-form-card">
      <header class="form-card-header meal-session-form-header">
        <div class="form-card-header-left">
          <div class="form-card-header-icon" aria-hidden="true">
            <i class="fa-solid fa-utensils"></i>
          </div>
          <div class="form-card-header-text">
            <h1 class="form-card-title">{{ isAddMode ? 'Add Meal Session' : 'Edit Meal Session' }}</h1>
            <p class="form-card-subtitle">
              {{ isAddMode
                ? 'Create a meal session with name, time range and status.'
                : 'Update meal session name, time range and status.' }}
            </p>
          </div>
        </div>
        <span class="meal-session-mode-chip">{{ isAddMode ? 'Add mode' : 'Edit mode' }}</span>
      </header>

      <div class="form-card-body meal-session-form-body">
        <section class="section-card meal-session-section">
          <div class="section-header">
            <i class="fa-solid fa-clock"></i>
            <span class="header-title">Session details</span>
          </div>
          <div class="section-body row g-2">
            <div class="col-12 col-md-4">
              <label class="form-label">Session Name <span class="text-danger">*</span></label>
              <dx-select-box
                formControlName="sessionNameId"
                [items]="sessionNames"
                displayExpr="name"
                valueExpr="id"
                placeholder="Select session name"
                [readOnly]="!isAddMode"
              ></dx-select-box>
              @if (hasError('sessionNameId', 'required')) {
                <div class="text-danger small mt-1">Session name is required.</div>
              }
            </div>
            <div class="col-12 col-md-4">
              <label class="form-label">Start Time <span class="text-danger">*</span></label>
              <dx-text-box
                formControlName="startTime"
                placeholder="HH:mm"
                [inputAttr]="{ maxlength: '5', inputmode: 'numeric' }"
                (onInput)="onTimeInput('startTime', $event)"
                (onFocusOut)="onTimeBlur('startTime')"
