using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Interface;
using SolutionOne_BusinessLogicLayer.Services.Common.Interface;
using SolutionOne_Core.CanteenManagementModels.MealBooking;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.Utilities;
using SolutionOne_DataAccessLayer.Entities;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;
using System.Net;

namespace SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Implementation;

public class MealBookingService : IMealBookingService
{
    // Hard ceiling on one CancelMeals request; BookMeals is bounded by MaxDatesPerRequest x sessions.
    private const int MaxBookingIdsPerRequest = 200;

    private readonly IMealBookingRepository _repository;
    private readonly IMealSessionRepository _mealSessionRepository;
    private readonly IRequestMetadata _meta;
    private readonly MealBookingSettings _settings;
    private readonly TimeProvider _clock;
    private readonly ILogger<MealBookingService> _logger;

    public MealBookingService(
        IMealBookingRepository repository,
        IMealSessionRepository mealSessionRepository,
        IRequestMetadata meta,
        IOptions<MealBookingSettings> settings,
        TimeProvider clock,
        ILogger<MealBookingService> logger)
    {
        _repository = repository;
        _mealSessionRepository = mealSessionRepository;
        _meta = meta;
        _settings = settings.Value;
        _clock = clock;
        _logger = logger;
    }

    public async Task<(ResponseModel, List<MealBookingModel>)> GetMyBookingsAsync(DateOnly? fromDate, DateOnly? toDate)
    {
        var (response, employee) = await GetLoggedInEmployeeAsync();
        if (employee == null)
            return (response, new List<MealBookingModel>());

        var zone = ResolveTimeZone(employee);
        var today = DateOnly.FromDateTime(TimeZoneLookup.FromUtc(UtcNow, zone));
        var from = fromDate ?? today;
        var to = toDate ?? from.AddDays(30);

        if (to < from)
            return (Fail(HttpStatusCode.BadRequest, "toDate must be on or after fromDate."), new List<MealBookingModel>());

        if (to.DayNumber - from.DayNumber + 1 > _settings.MaxRangeDays)
            return (Fail(HttpStatusCode.BadRequest, $"The date range can be at most {_settings.MaxRangeDays} days."), new List<MealBookingModel>());

        var list = (await _repository.GetBookedAsync(employee.EmployeeMasterId, from, to))
            .Select(x => new MealBookingModel
            {
                BookingId = x.BookingId,
                MealDate = x.MealDate,
                MSessionId = x.MSessionId,
                SessionName = x.MealSession?.SessionNameNavigation?.SessionName ?? string.Empty,
                CanteenFacilityType = x.CanteenFacilityType,
                EmployeeShare = x.EmployeeShare,
                CompanyShare = x.CompanyShare,
                BookedOn = TimeZoneLookup.FromUtc(x.BookedOnUtc, zone)
            })
            .ToList();

        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        return (response, list);
    }

    public async Task<(ResponseModel, List<BookMealResult>)> BookMealsAsync(BookMealsRequest request)
    {
        var dates = (request?.Dates ?? new List<DateOnly>()).Distinct().OrderBy(x => x).ToList();
        var sessionIds = (request?.MSessionIds ?? new List<int>()).Distinct().ToList();

        if (dates.Count == 0 || sessionIds.Count == 0)
            return (Fail(HttpStatusCode.BadRequest, "Select at least one date and one meal."), new List<BookMealResult>());

        if (dates.Count > _settings.MaxDatesPerRequest)
            return (Fail(HttpStatusCode.BadRequest, $"At most {_settings.MaxDatesPerRequest} dates can be booked at once."), new List<BookMealResult>());

        var (response, employee) = await GetLoggedInEmployeeAsync();
        if (employee == null)
            return (response, new List<BookMealResult>());

        if (!employee.IsCanteenFacility)
            return (Fail(HttpStatusCode.BadRequest, CanteenMealRates.FacilityNotEnabledMessage), new List<BookMealResult>());

        var zone = ResolveTimeZone(employee);
        var nowUtc = UtcNow;
        var facilityType = CanteenMealRates.FacilityTypeOf(employee);

        var sessions = (await _mealSessionRepository.GetAllAsync())
            .Where(x => sessionIds.Contains(x.MSessionId))
            .ToDictionary(x => x.MSessionId);
        // Results read in meal order (breakfast before lunch); unknown ids go last.
        var orderedSessionIds = sessionIds
            .OrderBy(id => sessions.TryGetValue(id, out var s) ? s.StartTime : TimeOnly.MaxValue)
            .ToList();

        var alreadyBooked = await _repository.GetBookedKeysAsync(employee.EmployeeMasterId, dates, sessionIds);
        var menuDays = await _repository.GetMenuDaysAsync(dates, sessionIds);

        var results = new List<BookMealResult>();
        var toInsert = new List<(BookMealResult Result, HrCmsMealBooking Booking)>();
        var userId = _meta.TryGetUserId(out var uid) ? uid : 0;

        foreach (var date in dates)
        {
            foreach (var sessionId in orderedSessionIds)
            {
                sessions.TryGetValue(sessionId, out var session);
                var result = new BookMealResult
                {
                    MealDate = date,
                    MSessionId = sessionId,
                    SessionName = session?.SessionNameNavigation?.SessionName ?? string.Empty
                };
                results.Add(result);

                if (session == null || !session.IsActive)
                {
                    SetResult(result, BookMealResultStatuses.InvalidMealSession, "This meal session does not exist or is not active.");
                    continue;
                }

                if (alreadyBooked.Contains((date, sessionId)))
                {
                    SetResult(result, BookMealResultStatuses.AlreadyBooked, "You have already booked this meal.");
                    continue;
                }

                var mealStartUtc = MealStartUtc(date, session, zone);
                if (nowUtc > mealStartUtc.AddHours(-_settings.BookingCloseHours))
                {
                    SetResult(result, BookMealResultStatuses.BookingClosed,
                        $"Booking closes {FormatHours(_settings.BookingCloseHours)} before the meal starts.");
                    continue;
                }

                if (!menuDays.Contains((date, sessionId)))
                {
                    SetResult(result, BookMealResultStatuses.NoMenu, "No menu is planned for this meal on this day.");
                    continue;
                }

                var (companyShare, employeeShare) = CanteenMealRates.For(session, facilityType);
                toInsert.Add((result, new HrCmsMealBooking
                {
                    EmployeeMasterId = employee.EmployeeMasterId,
                    MSessionId = sessionId,
                    MealDate = date,
                    CanteenFacilityType = facilityType,
                    CompanyShare = companyShare,
                    EmployeeShare = employeeShare,
                    Status = MealBookingStatuses.Booked,
                    BookedOnUtc = nowUtc,
                    CreatedById = userId
                }));
            }
        }

        var inserted = await _repository.AddBookingsAsync(toInsert.Select(x => x.Booking).ToList());
        for (var i = 0; i < toInsert.Count; i++)
        {
            var (result, booking) = toInsert[i];
            if (inserted[i])
            {
                SetResult(result, BookMealResultStatuses.Booked, "Booked.");
                result.BookingId = booking.BookingId;
                result.EmployeeShare = booking.EmployeeShare;
                result.CompanyShare = booking.CompanyShare;
            }
            else
            {
                SetResult(result, BookMealResultStatuses.AlreadyBooked, "You have already booked this meal.");
            }
        }

        var bookedCount = results.Count(x => x.Status == BookMealResultStatuses.Booked);
        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        response.Message = $"{bookedCount} of {results.Count} meal(s) booked.";
        return (response, results);
    }

    public async Task<(ResponseModel, List<CancelMealResult>)> CancelMealsAsync(CancelMealsRequest request)
    {
        var bookingIds = (request?.BookingIds ?? new List<long>()).Distinct().ToList();

        if (bookingIds.Count == 0)
            return (Fail(HttpStatusCode.BadRequest, "Select at least one booking to cancel."), new List<CancelMealResult>());

        if (bookingIds.Count > MaxBookingIdsPerRequest)
            return (Fail(HttpStatusCode.BadRequest, $"At most {MaxBookingIdsPerRequest} bookings can be cancelled at once."), new List<CancelMealResult>());

        // No Canteen Facility check here: an employee whose facility was switched off can still cancel
        // meals they booked before.
        var (response, employee) = await GetLoggedInEmployeeAsync();
        if (employee == null)
            return (response, new List<CancelMealResult>());

        var zone = ResolveTimeZone(employee);
        var nowUtc = UtcNow;
        var userId = _meta.TryGetUserId(out var uid) ? uid : (long?)null;

        // Only the employee's own active bookings come back, so another employee's booking or one already
        // cancelled reads as "Not found" - the API never confirms someone else's booking exists.
        var bookings = (await _repository.GetBookedByIdsAsync(employee.EmployeeMasterId, bookingIds))
            .ToDictionary(x => x.BookingId);

        var results = new List<CancelMealResult>();
        var anyCancelled = false;

        foreach (var bookingId in bookingIds)
        {
            var result = new CancelMealResult { BookingId = bookingId };
            results.Add(result);

            if (!bookings.TryGetValue(bookingId, out var booking) || booking.MealSession == null)
            {
                result.Status = CancelMealResultStatuses.NotFound;
                result.Message = "Booking not found.";
                continue;
            }

            var mealStartUtc = MealStartUtc(booking.MealDate, booking.MealSession, zone);
            if (nowUtc > mealStartUtc.AddHours(-_settings.CancelCutoffHours))
            {
                result.Status = CancelMealResultStatuses.TooLate;
                result.Message = $"Meals can only be cancelled up to {FormatHours(_settings.CancelCutoffHours)} before they start.";
                continue;
            }

            booking.Status = MealBookingStatuses.Cancelled;
            booking.CancelledOnUtc = nowUtc;
            booking.ModifiedById = userId;
            anyCancelled = true;

            result.Status = CancelMealResultStatuses.Cancelled;
            result.Message = "Booking cancelled.";
        }

        if (anyCancelled)
            await _repository.SaveChangesAsync();

        var cancelledCount = results.Count(x => x.Status == CancelMealResultStatuses.Cancelled);
        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        response.Message = $"{cancelledCount} of {results.Count} booking(s) cancelled.";
        return (response, results);
    }

    private DateTime UtcNow => _clock.GetUtcNow().UtcDateTime;

    /// <summary>The employee from the login token. On failure the employee is null and the response says why.</summary>
    private async Task<(ResponseModel, HrEmployeeMaster?)> GetLoggedInEmployeeAsync()
    {
        if (!_meta.TryGetEmployeeMasterId(out var employeeMasterId) || employeeMasterId <= 0)
            return (Fail(HttpStatusCode.BadRequest, "This login is not linked to an employee."), null);

        var employee = await _mealSessionRepository.GetEmployeeCanteenInfoAsync(employeeMasterId);
        if (employee == null)
            return (Fail(HttpStatusCode.NotFound, "Employee not found."), null);

        return (new ResponseModel(), employee);
    }

    /// <summary>The canteen's time zone for this employee: branch entry, then company entry, then the default.</summary>
    private TimeZoneInfo ResolveTimeZone(HrEmployeeMaster employee)
    {
        string? id = null;
        if (employee.BranchMasterId.HasValue)
            _settings.BranchTimeZones.TryGetValue(employee.BranchMasterId.Value.ToString(), out id);
        if (string.IsNullOrWhiteSpace(id))
            _settings.CompanyTimeZones.TryGetValue(employee.CompanyMasterId.ToString(), out id);
        if (string.IsNullOrWhiteSpace(id))
            id = _settings.DefaultTimeZoneId;

        var zone = TimeZoneLookup.Find(id);
        if (zone != null)
            return zone;

        _logger.LogWarning("MealBooking: time zone '{TimeZoneId}' for employee {EmployeeMasterId} is not known on this server; using DefaultTimeZoneId.",
            id, employee.EmployeeMasterId);
        return TimeZoneLookup.Find(_settings.DefaultTimeZoneId) ?? TimeZoneLookup.Find("India Standard Time") ?? TimeZoneInfo.Utc;
    }

    private static DateTime MealStartUtc(DateOnly mealDate, HrCmsMealSession session, TimeZoneInfo zone) =>
        TimeZoneLookup.ToUtc(mealDate.ToDateTime(session.StartTime), zone);

    private static void SetResult(BookMealResult result, string status, string message)
    {
        result.Status = status;
        result.Message = message;
    }

    private static string FormatHours(double hours) => hours == 1 ? "1 hour" : $"{hours:0.##} hours";

    private static ResponseModel Fail(HttpStatusCode status, string message) => new()
    {
        IsSuccess = false,
        Status = status,
        Message = message
    };
}

