using SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Interface;
using SolutionOne_Core.CanteenManagementModels.MealSession;
using SolutionOne_Core.CommonModels;
using SolutionOne_DataAccessLayer.Entities;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;
using System.Net;

namespace SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Implementation;

public class MealSessionService : IMealSessionService
{
    private readonly IMealSessionRepository _repository;
    private readonly IItemMasterRepository _itemMasterRepository;
    private readonly ApplicationSession _applicationSession;

    public MealSessionService(
        IMealSessionRepository repository,
        IItemMasterRepository itemMasterRepository,
        ApplicationSession applicationSession)
    {
        _repository = repository;
        _itemMasterRepository = itemMasterRepository;
        _applicationSession = applicationSession;
    }

    public async Task<(ResponseModel, List<MealSessionModel>)> GetAllMealSessionsAsync()
    {
        var response = new ResponseModel { IsSuccess = true, Status = HttpStatusCode.OK };
        var entities = await _repository.GetAllAsync();
        var list = entities.Select(MapModel).ToList();
        return (response, list);
    }

    public async Task<(ResponseModel, List<SessionNameModel>)> GetAllSessionNamesAsync()
    {
        var response = new ResponseModel { IsSuccess = true, Status = HttpStatusCode.OK };
        var list = (await _repository.GetAllSessionNamesAsync())
            .Select(x => new SessionNameModel
            {
                SessionNameId = x.SessionNameId,
                SessionName = x.SessionName
            })
            .ToList();

        return (response, list);
    }

    public async Task<(ResponseModel, MealSessionModel?)> GetMealSessionByIdAsync(int id)
    {
        var response = new ResponseModel();
        var entity = await _repository.GetByIdAsync(id);
        if (entity == null)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.NotFound;
            response.Message = "Meal session not found.";
            return (response, null);
        }

        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        return (response, MapModel(entity));
    }

    public async Task<ResponseModel> InsertMealSessionAsync(MealSessionSaveModel model)
    {
        var response = new ResponseModel();
        var validation = await ValidateAsync(model, isInsert: true);
        if (validation != null)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.BadRequest;
            response.Message = validation;
            return response;
        }

        var entity = new HrCmsMealSession
        {
            SessionNameId = model.SessionNameId,
            StartTime = ParseTime(model.StartTime),
            EndTime = ParseTime(model.EndTime),
            IsActive = model.IsActive,
            CompanyShare = model.CompanyShare,
            EmployeeShare = model.EmployeeShare,
            AdhocCompanyShare = model.AdhocCompanyShare,
            AdhocEmployeeShare = model.AdhocEmployeeShare,
            CreateDate = DateTime.Now,
            CreatedById = _applicationSession.UserMasterID ?? 0
        };

        await _repository.AddAsync(entity);
        response.IsSuccess = true;
        response.Status = HttpStatusCode.Created;
        response.Message = "Meal session added.";
        response.Data = new { entity.MSessionId };
        return response;
    }

    public async Task<ResponseModel> UpdateMealSessionAsync(MealSessionSaveModel model)
    {
        var response = new ResponseModel();
        var entity = await _repository.GetByIdAsync(model.MSessionId);
        if (entity == null)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.NotFound;
            response.Message = "Meal session not found.";
            return response;
        }

        var validation = await ValidateAsync(model, isInsert: false);
        if (validation != null)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.BadRequest;
            response.Message = validation;
            return response;
        }

        if (model.SessionNameId != entity.SessionNameId)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.BadRequest;
            response.Message = "Session name cannot be changed. Edit the existing meal session for that name.";
            return response;
        }
        entity.StartTime = ParseTime(model.StartTime);
        entity.EndTime = ParseTime(model.EndTime);
        entity.IsActive = model.IsActive;
        entity.CompanyShare = model.CompanyShare;
        entity.EmployeeShare = model.EmployeeShare;
        entity.AdhocCompanyShare = model.AdhocCompanyShare;
        entity.AdhocEmployeeShare = model.AdhocEmployeeShare;
        entity.ModifiedDate = DateTime.Now;
        entity.ModifiedById = _applicationSession.UserMasterID ?? 0;

        await _repository.UpdateAsync(entity);
        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        response.Message = "Meal session updated.";
        return response;
    }

    public async Task<ResponseModel> DeleteMealSessionAsync(int id)
    {
        var response = new ResponseModel();
        var entity = await _repository.GetByIdAsync(id);
        if (entity == null)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.NotFound;
            response.Message = "Meal session not found.";
            return response;
        }

        if (await _itemMasterRepository.ExistsForMealSessionAsync(id))
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.Conflict;
            response.Message = "This meal session is used in Item Master. Remove or reassign those items first.";
            return response;
        }

        await _repository.DeleteAsync(id);
        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        response.Message = "Meal session deleted.";
        return response;
    }

    /// <summary>Per-session rate for one employee: Daily employees get CompanyShare/EmployeeShare,
    /// Adhoc employees get AdhocCompanyShare/AdhocEmployeeShare. Use this wherever a meal is charged
    /// (meal entry, monthly canteen deduction) so the employee's facility type is applied in one place.</summary>
    public async Task<(ResponseModel, List<EmployeeMealRateModel>)> GetEmployeeMealRatesAsync(long employeeMasterId)
    {
        var response = new ResponseModel();
        var employee = await _repository.GetEmployeeCanteenInfoAsync(employeeMasterId);
        if (employee == null)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.NotFound;
            response.Message = "Employee not found.";
            return (response, new List<EmployeeMealRateModel>());
        }

        if (!employee.IsCanteenFacility)
        {
            response.IsSuccess = false;
            response.Status = HttpStatusCode.BadRequest;
            response.Message = CanteenMealRates.FacilityNotEnabledMessage;
            return (response, new List<EmployeeMealRateModel>());
        }

        var type = CanteenMealRates.FacilityTypeOf(employee);

        var list = (await _repository.GetAllAsync())
            .Where(x => x.IsActive)
            .Select(x =>
            {
                var (companyShare, employeeShare) = CanteenMealRates.For(x, type);
                return new EmployeeMealRateModel
                {
                    MSessionId = x.MSessionId,
                    SessionNameId = x.SessionNameId,
                    SessionName = x.SessionNameNavigation?.SessionName ?? string.Empty,
                    StartTime = x.StartTime.ToString("HH:mm:ss"),
                    EndTime = x.EndTime.ToString("HH:mm:ss"),
                    CanteenFacilityType = type,
                    CompanyShare = companyShare,
                    EmployeeShare = employeeShare
                };
            })
            .ToList();

        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        return (response, list);
    }

    private static MealSessionModel MapModel(HrCmsMealSession entity) => new()
    {
        MSessionId = entity.MSessionId,
        SessionNameId = entity.SessionNameId,
        SessionName = entity.SessionNameNavigation?.SessionName ?? string.Empty,
        StartTime = entity.StartTime.ToString("HH:mm:ss"),
        EndTime = entity.EndTime.ToString("HH:mm:ss"),
        IsActive = entity.IsActive,
        CompanyShare = entity.CompanyShare,
        EmployeeShare = entity.EmployeeShare,
        AdhocCompanyShare = entity.AdhocCompanyShare,
        AdhocEmployeeShare = entity.AdhocEmployeeShare
    };

    private async Task<string?> ValidateAsync(MealSessionSaveModel model, bool isInsert)
    {
        if (model.SessionNameId <= 0)
            return "Session name is required.";

        if (!await _repository.IsValidSessionNameIdAsync(model.SessionNameId))
            return "Please select a valid session name.";

        if (isInsert && await _repository.ExistsBySessionNameIdAsync(model.SessionNameId))
            return "A meal session already exists for this session name. Please edit the existing record.";

        if (!TimeOnly.TryParse(model.StartTime, out var start))
            return "Invalid start time.";

        if (!TimeOnly.TryParse(model.EndTime, out var end))
            return "Invalid end time.";

        if (end <= start)
            return "End time must be after start time.";

        if (model.CompanyShare < 0 || model.EmployeeShare < 0 || model.AdhocCompanyShare < 0 || model.AdhocEmployeeShare < 0)
            return "Company and employee shares cannot be negative.";

        return null;
    }

    private static TimeOnly ParseTime(string value) => TimeOnly.Parse(value);
}

