using System.Collections.Concurrent;

namespace SolutionOne_Core.Utilities;

/// <summary>
/// Resolves a configured time zone id on any host OS. Windows ids ("India Standard Time") and IANA
/// ids ("Asia/Kolkata") are both accepted on Windows and Linux; an unknown id returns null so the
/// caller can fall back instead of failing the request.
/// </summary>
public static class TimeZoneLookup
{
    private static readonly ConcurrentDictionary<string, TimeZoneInfo?> Cache = new(StringComparer.OrdinalIgnoreCase);

    public static TimeZoneInfo? Find(string? id)
    {
        if (string.IsNullOrWhiteSpace(id))
            return null;

        return Cache.GetOrAdd(id.Trim(), static key =>
        {
            if (TryFind(key, out var zone))
                return zone;
            if (TimeZoneInfo.TryConvertWindowsIdToIanaId(key, out var iana) && TryFind(iana, out zone))
                return zone;
            if (TimeZoneInfo.TryConvertIanaIdToWindowsId(key, out var windows) && TryFind(windows, out zone))
                return zone;
            return null;
        });
    }

    /// <summary>The UTC instant of a wall-clock time in <paramref name="zone"/>. A time skipped by a
    /// daylight-saving jump is moved past the gap rather than throwing.</summary>
    public static DateTime ToUtc(DateTime local, TimeZoneInfo zone)
    {
        local = DateTime.SpecifyKind(local, DateTimeKind.Unspecified);
        while (zone.IsInvalidTime(local))
            local = local.AddMinutes(30);
        return TimeZoneInfo.ConvertTimeToUtc(local, zone);
    }

    /// <summary>A UTC instant as wall-clock time in <paramref name="zone"/> (Kind = Unspecified, so it
    /// serialises without an offset - the shape the mobile app reads).</summary>
    public static DateTime FromUtc(DateTime utc, TimeZoneInfo zone) =>
        DateTime.SpecifyKind(TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(utc, DateTimeKind.Utc), zone), DateTimeKind.Unspecified);

    private static bool TryFind(string id, out TimeZoneInfo? zone)
    {
        try
        {
            zone = TimeZoneInfo.FindSystemTimeZoneById(id);
            return true;
        }
        catch (TimeZoneNotFoundException) { }
        catch (InvalidTimeZoneException) { }
        zone = null;
        return false;
    }
}

