using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Options;
using Moq;
using SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Implementation;
using SolutionOne_BusinessLogicLayer.Services.Common.Interface;
using SolutionOne_Core.CanteenManagementModels.MealBooking;
using SolutionOne_Core.CanteenManagementModels.MealSession;
