using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;
using System.Net;
using Xunit;

namespace SolutionOne_Tests;

/// <summary>
/// Meal booking charges employees and decides who eats: the cutoffs must be measured in the canteen's
/// own time zone, the price must follow the employee's Meal Plan, and one employee can never touch
/// another's booking.
/// </summary>
public class MealBookingServiceTests
{
    private const long EmployeeId = 501;
    private const long UserId = 77;
    private const int Lunch = 2;
    private const int Dinner = 3;
    private static readonly DateOnly Oct25 = new(2026, 10, 25);

    private readonly Mock<IMealBookingRepository> _bookings = new();
    private readonly Mock<IMealSessionRepository> _sessions = new();
    private readonly Mock<IRequestMetadata> _meta = new();
    private readonly MealBookingSettings _settings = new();
    private readonly HrEmployeeMaster _employee = new()
    {
        EmployeeMasterId = EmployeeId,
        CompanyMasterId = 1,
        IsCanteenFacility = true,
        CanteenFacilityType = CanteenFacilityTypes.Adhoc
    };

    public MealBookingServiceTests()
    {
        long emp = EmployeeId, user = UserId;
        _meta.Setup(x => x.TryGetEmployeeMasterId(out emp)).Returns(true);
        _meta.Setup(x => x.TryGetUserId(out user)).Returns(true);
        _sessions.Setup(x => x.GetEmployeeCanteenInfoAsync(EmployeeId)).ReturnsAsync(_employee);
        _sessions.Setup(x => x.GetAllAsync()).ReturnsAsync(new List<HrCmsMealSession>
        {
            Session(Lunch, "Lunch", new TimeOnly(12, 0), isActive: true),
            Session(Dinner, "Dinner", new TimeOnly(20, 0), isActive: false)
        });
        _bookings.Setup(x => x.GetBookedKeysAsync(EmployeeId, It.IsAny<IReadOnlyCollection<DateOnly>>(), It.IsAny<IReadOnlyCollection<int>>()))
            .ReturnsAsync(new HashSet<(DateOnly, int)>());
        _bookings.Setup(x => x.GetMenuDaysAsync(It.IsAny<IReadOnlyCollection<DateOnly>>(), It.IsAny<IReadOnlyCollection<int>>()))
            .ReturnsAsync(new HashSet<(DateOnly, int)> { (Oct25, Lunch) });
        _bookings.Setup(x => x.AddBookingsAsync(It.IsAny<IReadOnlyList<HrCmsMealBooking>>()))
            .ReturnsAsync((IReadOnlyList<HrCmsMealBooking> rows) =>
            {
                for (var i = 0; i < rows.Count; i++) rows[i].BookingId = 1000 + i;
                return rows.Select(_ => true).ToList();
            });
    }

    [Fact]
    public async Task An_employee_without_canteen_facility_is_refused_outright()
    {
        _employee.IsCanteenFacility = false;

        var (response, results) = await Service(Utc(2026, 10, 23, 6, 0)).BookMealsAsync(Request(Oct25, Lunch));

        Assert.Equal(HttpStatusCode.BadRequest, response.Status);
        Assert.Equal("Canteen facility is not enabled for this employee.", response.Message);
        Assert.Empty(results);
        _bookings.Verify(x => x.AddBookingsAsync(It.IsAny<IReadOnlyList<HrCmsMealBooking>>()), Times.Never);
    }

    [Fact]
    public async Task A_login_without_an_employee_cannot_book()
    {
        long none = 0;
        _meta.Setup(x => x.TryGetEmployeeMasterId(out none)).Returns(false);

        var (response, _) = await Service(Utc(2026, 10, 23, 6, 0)).BookMealsAsync(Request(Oct25, Lunch));

        Assert.Equal(HttpStatusCode.BadRequest, response.Status);
    }

    [Fact]
    public async Task A_booked_meal_is_charged_the_adhoc_rate_of_an_adhoc_employee()
    {
        var (response, results) = await Service(Utc(2026, 10, 23, 6, 0)).BookMealsAsync(Request(Oct25, Lunch));

        var result = Assert.Single(results);
        Assert.Equal(HttpStatusCode.OK, response.Status);
        Assert.Equal(BookMealResultStatuses.Booked, result.Status);
        Assert.Equal(1000, result.BookingId);
        Assert.Equal(15m, result.EmployeeShare);   // Adhoc, not the Daily 10
        Assert.Equal(45m, result.CompanyShare);
        _bookings.Verify(x => x.AddBookingsAsync(It.Is<IReadOnlyList<HrCmsMealBooking>>(rows =>
            rows.Single().EmployeeMasterId == EmployeeId
            && rows.Single().CanteenFacilityType == CanteenFacilityTypes.Adhoc
            && rows.Single().Status == MealBookingStatuses.Booked
            && rows.Single().CreatedById == UserId)));
    }

    [Fact]
    public async Task Each_meal_gets_its_own_outcome()
    {
        var oct26 = Oct25.AddDays(1);
        var oct22 = new DateOnly(2026, 10, 22);
        _bookings.Setup(x => x.GetBookedKeysAsync(EmployeeId, It.IsAny<IReadOnlyCollection<DateOnly>>(), It.IsAny<IReadOnlyCollection<int>>()))
            .ReturnsAsync(new HashSet<(DateOnly, int)> { (oct26, Lunch) });

        var request = new BookMealsRequest { Dates = new() { Oct25, oct26, oct22, new DateOnly(2026, 10, 27) }, MSessionIds = new() { Lunch, Dinner, 99 } };
        var (_, results) = await Service(Utc(2026, 10, 23, 6, 0)).BookMealsAsync(request);

        string StatusOf(DateOnly d, int s) => results.Single(r => r.MealDate == d && r.MSessionId == s).Status;
        Assert.Equal(12, results.Count);
        Assert.Equal(BookMealResultStatuses.Booked, StatusOf(Oct25, Lunch));
        Assert.Equal(BookMealResultStatuses.AlreadyBooked, StatusOf(oct26, Lunch));
        Assert.Equal(BookMealResultStatuses.BookingClosed, StatusOf(oct22, Lunch));

