    [Fact]
    public async Task The_cutoff_follows_the_company_time_zone_not_the_server()
    {
        // 05:30 UTC: 11:00 in India (1 hour to lunch - closed) but 09:30 in Dubai (2.5 hours - open).
        var now = Utc(2026, 10, 25, 5, 30);

        var (_, inIndia) = await Service(now).BookMealsAsync(Request(Oct25, Lunch));
        _settings.CompanyTimeZones["1"] = "Asia/Dubai";
        var (_, inDubai) = await Service(now).BookMealsAsync(Request(Oct25, Lunch));

