    private static BookMealsRequest Request(DateOnly date, int sessionId) =>
        new() { Dates = new() { date }, MSessionIds = new() { sessionId } };

    private static DateTime Utc(int y, int m, int d, int h, int min) => new(y, m, d, h, min, 0, DateTimeKind.Utc);

    private static HrCmsMealSession Session(int id, string name, TimeOnly start, bool isActive) => new()
    {
        MSessionId = id,
        StartTime = start,
        EndTime = start.AddHours(2),
        IsActive = isActive,
