    // Lunch 12:00 IST = 06:30 UTC; closes 2 hours earlier at 04:30 UTC.
    [InlineData(4, 29, BookMealResultStatuses.Booked)]
    [InlineData(4, 31, BookMealResultStatuses.BookingClosed)]
    public async Task Booking_closes_two_hours_before_the_meal_in_india_time(int utcHour, int utcMinute, string expected)
    {
        var (_, results) = await Service(Utc(2026, 10, 25, utcHour, utcMinute)).BookMealsAsync(Request(Oct25, Lunch));

        Assert.Equal(expected, Assert.Single(results).Status);
    }

    [Fact]
    public async Task The_cutoff_follows_the_company_time_zone_not_the_server()
    {
        // 05:30 UTC: 11:00 in India (1 hour to lunch - closed) but 09:30 in Dubai (2.5 hours - open).
        var now = Utc(2026, 10, 25, 5, 30);

        var (_, inIndia) = await Service(now).BookMealsAsync(Request(Oct25, Lunch));
        _settings.CompanyTimeZones["1"] = "Asia/Dubai";
        var (_, inDubai) = await Service(now).BookMealsAsync(Request(Oct25, Lunch));

        Assert.Equal(BookMealResultStatuses.BookingClosed, Assert.Single(inIndia).Status);
        Assert.Equal(BookMealResultStatuses.Booked, Assert.Single(inDubai).Status);
    }

    [Fact]
    public async Task A_meal_booked_by_a_parallel_request_reads_as_already_booked()
    {
        _bookings.Setup(x => x.AddBookingsAsync(It.IsAny<IReadOnlyList<HrCmsMealBooking>>()))
            .ReturnsAsync(new List<bool> { false });

        var (_, results) = await Service(Utc(2026, 10, 23, 6, 0)).BookMealsAsync(Request(Oct25, Lunch));

        var result = Assert.Single(results);
        Assert.Equal(BookMealResultStatuses.AlreadyBooked, result.Status);
        Assert.Null(result.BookingId);
    }

    [Fact]
    public async Task Cancel_allows_up_to_24_hours_before_the_meal_and_hides_other_peoples_bookings()
    {
        var early = Booking(1, Oct25.AddDays(2));
        var late = Booking(2, Oct25);
        _bookings.Setup(x => x.GetBookedByIdsAsync(EmployeeId, It.IsAny<IReadOnlyCollection<long>>()))
            .ReturnsAsync(new List<HrCmsMealBooking> { early, late });   // id 3 belongs to someone else

        // 24 Oct 13:00 IST: 23 hours before lunch on the 25th.
        var (response, results) = await Service(Utc(2026, 10, 24, 7, 30))
            .CancelMealsAsync(new CancelMealsRequest { BookingIds = new() { 1, 2, 3 } });

        Assert.Equal(HttpStatusCode.OK, response.Status);
        Assert.Equal(CancelMealResultStatuses.Cancelled, results.Single(r => r.BookingId == 1).Status);
        Assert.Equal(CancelMealResultStatuses.TooLate, results.Single(r => r.BookingId == 2).Status);
        Assert.Equal(CancelMealResultStatuses.NotFound, results.Single(r => r.BookingId == 3).Status);
        Assert.Equal(MealBookingStatuses.Cancelled, early.Status);
        Assert.Equal(UserId, early.ModifiedById);
        Assert.Equal(MealBookingStatuses.Booked, late.Status);
        _bookings.Verify(x => x.SaveChangesAsync(), Times.Once);
    }

    [Fact]
    public async Task My_bookings_show_booked_on_in_the_canteens_local_time()
    {
        var booking = Booking(9, Oct25);
        booking.BookedOnUtc = Utc(2026, 10, 23, 4, 0);
        _bookings.Setup(x => x.GetBookedAsync(EmployeeId, Oct25, Oct25)).ReturnsAsync(new List<HrCmsMealBooking> { booking });

        var (_, list) = await Service(Utc(2026, 10, 23, 6, 0)).GetMyBookingsAsync(Oct25, Oct25);

        var item = Assert.Single(list);
        Assert.Equal(new DateTime(2026, 10, 23, 9, 30, 0), item.BookedOn);   // 04:00 UTC = 09:30 IST
        Assert.Equal(DateTimeKind.Unspecified, item.BookedOn.Kind);
        Assert.Equal("Lunch", item.SessionName);
    }

    [Fact]
    public async Task My_bookings_rejects_a_reversed_range()
    {
        var (response, _) = await Service(Utc(2026, 10, 23, 6, 0)).GetMyBookingsAsync(Oct25, Oct25.AddDays(-1));

        Assert.Equal(HttpStatusCode.BadRequest, response.Status);
    }

    private MealBookingService Service(DateTime utcNow) => new(
        _bookings.Object,
        _sessions.Object,
        _meta.Object,
        Options.Create(_settings),
        new FixedClock(utcNow),
        NullLogger<MealBookingService>.Instance);

    private static BookMealsRequest Request(DateOnly date, int sessionId) =>
        new() { Dates = new() { date }, MSessionIds = new() { sessionId } };

    private static DateTime Utc(int y, int m, int d, int h, int min) => new(y, m, d, h, min, 0, DateTimeKind.Utc);

    private static HrCmsMealSession Session(int id, string name, TimeOnly start, bool isActive) => new()
    {
        MSessionId = id,
        StartTime = start,
        EndTime = start.AddHours(2),
        IsActive = isActive,
        CompanyShare = 40,
        EmployeeShare = 10,
        AdhocCompanyShare = 45,
        AdhocEmployeeShare = 15,
        SessionNameNavigation = new HrCmsSessionName { SessionName = name }
    };

    private static HrCmsMealBooking Booking(long id, DateOnly date) => new()
    {
        BookingId = id,
        EmployeeMasterId = EmployeeId,
        MSessionId = Lunch,
        MealDate = date,
        CanteenFacilityType = CanteenFacilityTypes.Daily,
        Status = MealBookingStatuses.Booked,
        MealSession = Session(Lunch, "Lunch", new TimeOnly(12, 0), isActive: true)
    };

    private sealed class FixedClock(DateTime utcNow) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => new(utcNow, TimeSpan.Zero);
    }
}

