p='SolutionOne_Tests/MealBookingServiceTests.cs'
s=open(p).read()
def rep(old,new,n=1):
    global s
    assert old in s, "NOT FOUND: "+old[:90]
    s=s.replace(old,new,n)

rep("""/// Meal booking charges employees and decides who eats: the cutoffs must be measured in the canteen's
/// own time zone, the price must follow the employee's Meal Plan, and one employee can never touch
/// another's booking.""",
"""/// Meal booking charges employees and decides who eats: each meal session's own ordering deadline must
/// be measured in the canteen's own time zone, the price must follow the employee's Meal Plan, and one
/// employee can never touch another's booking.""")

rep("""    private const int Lunch = 2;
    private const int Dinner = 3;""",
"""    private const int Breakfast = 1;
    private const int Lunch = 2;
    private const int Dinner = 3;""")

rep("""        _sessions.Setup(x => x.GetAllAsync()).ReturnsAsync(new List<HrCmsMealSession>
        {
            Session(Lunch, "Lunch", new TimeOnly(12, 0), isActive: true),
            Session(Dinner, "Dinner", new TimeOnly(20, 0), isActive: false)
        });""",
"""        _sessions.Setup(x => x.GetAllAsync()).ReturnsAsync(new List<HrCmsMealSession>
        {
            // Breakfast closes the night before, lunch on the morning of the meal: the two shapes of deadline.
            Session(Breakfast, "Breakfast", new TimeOnly(8, 0), isActive: true, cutoff: new TimeOnly(23, 59), daysBefore: 1),
            Session(Lunch, "Lunch", new TimeOnly(12, 0), isActive: true),
            Session(Dinner, "Dinner", new TimeOnly(20, 0), isActive: false)
        });""")

rep("""            .ReturnsAsync(new HashSet<(DateOnly, int)> { (Oct25, Lunch) });""",
"""            .ReturnsAsync(new HashSet<(DateOnly, int)> { (Oct25, Lunch), (Oct25, Breakfast) });""")

rep("""    [Theory]
    // Lunch 12:00 IST = 06:30 UTC; closes 2 hours earlier at 04:30 UTC.
    [InlineData(4, 29, BookMealResultStatuses.Booked)]
    [InlineData(4, 31, BookMealResultStatuses.BookingClosed)]
    public async Task Booking_closes_two_hours_before_the_meal_in_india_time(int utcHour, int utcMinute, string expected)
    {
        var (_, results) = await Service(Utc(2026, 10, 25, utcHour, utcMinute)).BookMealsAsync(Request(Oct25, Lunch));

        Assert.Equal(expected, Assert.Single(results).Status);
    }""",
"""    [Theory]
    // Lunch is ordered by 09:30 on the day of the meal; 09:30 IST = 04:00 UTC. The deadline itself still counts.
    [InlineData(3, 59, BookMealResultStatuses.Booked)]
    [InlineData(4, 0, BookMealResultStatuses.Booked)]
    [InlineData(4, 1, BookMealResultStatuses.BookingClosed)]
    public async Task A_same_day_deadline_closes_ordering_at_its_own_clock_time(int utcHour, int utcMinute, string expected)
    {
        var (_, results) = await Service(Utc(2026, 10, 25, utcHour, utcMinute)).BookMealsAsync(Request(Oct25, Lunch));

        Assert.Equal(expected, Assert.Single(results).Status);
    }

    [Theory]
    // Breakfast on the 25th is ordered by 23:59 on the 24th; 23:59 IST = 18:29 UTC the same day.
    [InlineData(24, 18, 29, BookMealResultStatuses.Booked)]
    [InlineData(24, 18, 30, BookMealResultStatuses.BookingClosed)]
    [InlineData(25, 1, 0, BookMealResultStatuses.BookingClosed)]   // 06:30 IST on the day, 1.5 hours before it is served
    public async Task A_deadline_a_day_before_closes_ordering_the_evening_before(int utcDay, int utcHour, int utcMinute, string expected)
    {
        var (_, results) = await Service(Utc(2026, 10, utcDay, utcHour, utcMinute)).BookMealsAsync(Request(Oct25, Breakfast));

        Assert.Equal(expected, Assert.Single(results).Status);
    }

    [Fact]
    public async Task A_missed_deadline_says_which_moment_was_missed()
    {
        var (_, results) = await Service(Utc(2026, 10, 25, 4, 1)).BookMealsAsync(Request(Oct25, Lunch));

        var result = Assert.Single(results);
        Assert.Equal(BookMealResultStatuses.BookingClosed, result.Status);
        Assert.Equal("Ordering for this meal closed at 09:30 AM on 25 Oct 2026.", result.Message);
    }""")

rep("""        // 05:30 UTC: 11:00 in India (1 hour to lunch - closed) but 09:30 in Dubai (2.5 hours - open).""",
"""        // Lunch closes at 09:30. 05:30 UTC is 11:00 in India (closed) but exactly 09:30 in Dubai (still open).""")

rep("""    [Fact]
    public async Task Cancel_allows_up_to_24_hours_before_the_meal_and_hides_other_peoples_bookings()
    {
        var early = Booking(1, Oct25.AddDays(2));
        var late = Booking(2, Oct25);
        _bookings.Setup(x => x.GetBookedByIdsAsync(EmployeeId, It.IsAny<IReadOnlyCollection<long>>()))
            .ReturnsAsync(new List<HrCmsMealBooking> { early, late });   // id 3 belongs to someone else

        // 24 Oct 13:00 IST: 23 hours before lunch on the 25th.
        var (response, results) = await Service(Utc(2026, 10, 24, 7, 30))
            .CancelMealsAsync(new CancelMealsRequest { BookingIds = new() { 1, 2, 3 } });""",
"""    [Fact]
    public async Task Cancel_stops_at_the_same_deadline_as_ordering_and_hides_other_peoples_bookings()
    {
        var tomorrow = Booking(1, Oct25);
        var today = Booking(2, new DateOnly(2026, 10, 24));
        _bookings.Setup(x => x.GetBookedByIdsAsync(EmployeeId, It.IsAny<IReadOnlyCollection<long>>()))
            .ReturnsAsync(new List<HrCmsMealBooking> { tomorrow, today });   // id 3 belongs to someone else

        // 24 Oct 13:00 IST: today's lunch count went to the kitchen at 09:30, tomorrow's has not.
        var (response, results) = await Service(Utc(2026, 10, 24, 7, 30))
            .CancelMealsAsync(new CancelMealsRequest { BookingIds = new() { 1, 2, 3 } });""")

rep("""        Assert.Equal(CancelMealResultStatuses.NotFound, results.Single(r => r.BookingId == 3).Status);
        Assert.Equal(MealBookingStatuses.Cancelled, early.Status);
        Assert.Equal(UserId, early.ModifiedById);
        Assert.Equal(MealBookingStatuses.Booked, late.Status);""",
"""        Assert.Equal(CancelMealResultStatuses.NotFound, results.Single(r => r.BookingId == 3).Status);
        Assert.Equal(MealBookingStatuses.Cancelled, tomorrow.Status);
        Assert.Equal(UserId, tomorrow.ModifiedById);
        Assert.Equal(MealBookingStatuses.Booked, today.Status);""")

rep("""    private static HrCmsMealSession Session(int id, string name, TimeOnly start, bool isActive) => new()
    {
        MSessionId = id,
        StartTime = start,
        EndTime = start.AddHours(2),""",
"""    /// <summary>A meal session; without a deadline of its own it is ordered by 09:30 on the day of the meal.</summary>
    private static HrCmsMealSession Session(int id, string name, TimeOnly start, bool isActive, TimeOnly? cutoff = null, int daysBefore = 0) => new()
    {
        MSessionId = id,
        StartTime = start,
        EndTime = start.AddHours(2),
        OrderCutoffTime = cutoff ?? new TimeOnly(9, 30),
        OrderCutoffDaysBefore = daysBefore,""")

open(p,'w').write(s)
print("ok")
