  private normalize(row: Record<string, unknown>): Record<string, unknown> {
    return {
      mSessionId: Number(row['mSessionId'] ?? row['MSessionId'] ?? row['mealSessionId'] ?? 0),
      sessionName: String(row['sessionName'] ?? row['SessionName'] ?? ''),
      startTime: this.formatTime(row['startTime'] ?? row['StartTime']),
      endTime: this.formatTime(row['endTime'] ?? row['EndTime']),
      companyShare: Number(row['companyShare'] ?? row['CompanyShare'] ?? 0),
      employeeShare: Number(row['employeeShare'] ?? row['EmployeeShare'] ?? 0),
      adhocCompanyShare: Number(row['adhocCompanyShare'] ?? row['AdhocCompanyShare'] ?? 0),
      adhocEmployeeShare: Number(row['adhocEmployeeShare'] ?? row['AdhocEmployeeShare'] ?? 0),
    };
