@use '../../../../shared/styles/form-card.scss' as *;

:host {
  display: block;
  width: 100%;
}

.meal-session-form-page {
  width: 100%;
  padding-bottom: 24px;
}

.meal-session-form-wrap {
  position: relative;
  max-width: var(--page-content-max-width, 1100px);
  margin: 0 auto;
}

.meal-session-form-wrap--loading .form-card-body,
.meal-session-form-wrap--loading .meal-session-form-footer {
  opacity: 0.55;
  pointer-events: none;
}

.meal-session-form-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.65);
  font-weight: 600;
  color: var(--text-soft);
  z-index: 2;
}

.meal-session-form-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  overflow: visible;
}

:host ::ng-deep .meal-session-section.section-card {
  overflow: visible;
}

:host ::ng-deep .meal-session-section .section-body .row > [class*='col-'] {
  margin-bottom: 6px;
  overflow: visible;
}

