                [items]="cutoffDayOptions"
                displayExpr="label"
                valueExpr="value"
                placeholder="Select cutoff day"
              ></dx-select-box>
              @if (hasError('orderCutoffDaysBefore', 'required')) {
                <div class="text-danger small mt-1">Cutoff day is required.</div>
              }
            </div>

