private async Task<string?> ValidateAsync(MealSessionSaveModel model, bool isInsert, HrCmsMealSession? existing = null)
{
    if (model.SessionNameId <= 0)
        return "Session name is required.";

    if (!await _repository.IsValidSessionNameIdAsync(model.SessionNameId))
        return "Please select a valid session name.";

    if (isInsert && await _repository.ExistsBySessionNameIdAsync(model.SessionNameId))
        return "A meal session already exists for this session name. Please edit the existing record.";

    if (!TimeOnly.TryParse(model.StartTime, out var start))
        return "Invalid start time.";

    if (!TimeOnly.TryParse(model.EndTime, out var end))
        return "Invalid end time.";

    if (end <= start)
        return "End time must be after start time.";

    if (!TimeOnly.TryParse(model.OrderCutoffTime, out var cutoff))
        return "Invalid order cutoff time.";

    if (model.OrderCutoffDaysBefore < 0 || model.OrderCutoffDaysBefore > MealOrderCutoff.MaxDaysBeforeCeiling)
        return $"The ordering deadline can be 0 to {MealOrderCutoff.MaxDaysBeforeCeiling} days before the meal.";

    if (model.OrderCutoffDaysBefore > MaxDaysBefore && model.OrderCutoffDaysBefore != existing?.OrderCutoffDaysBefore)
        return MaxDaysBefore == 0
            ? "The ordering deadline must fall on the day of the meal."
            : $"The ordering deadline can be at most {MealOrderCutoff.DayLabel(MaxDaysBefore)}.";

    // Ordering on the day of the meal has to close by the time the meal starts, or nobody could ever
    // meet it: breakfast served from 07:30 cannot be ordered at 08:00 that morning.
    if (model.OrderCutoffDaysBefore == 0 && cutoff > start)
        return $"Ordering must close by the time the meal starts ({start:HH:mm}). Choose an earlier time, or move the deadline to a day before the meal.";

    if (model.CompanyShare < 0 || model.EmployeeShare < 0 || model.AdhocCompanyShare < 0 || model.AdhocEmployeeShare < 0)
        return "Company and employee shares cannot be negative.";

    return null;
}

