  }

  /// The label of the chosen Cutoff Day, e.g. "1 day before the meal".
  get cutoffDayLabel(): string {
    const days = Number(this.mealSessionForm.getRawValue().orderCutoffDaysBefore ?? 0);
    return this.cutoffDayOptions.find((x) => x.value === days)?.label ?? '';
  }

  /// The deadline spelled out the way an employee would say it, so whoever is configuring the session
  /// reads back the rule they just typed rather than two numbers.
  get cutoffSummary(): string {
    const v = this.mealSessionForm.getRawValue();
    const cutoff = MealSessionFormComponent.toMinutes(v.orderCutoffTime);
    if (cutoff === null) return '';

    const days = Number(v.orderCutoffDaysBefore ?? 0);
    const when = days === 0 ? 'on the day of the meal' : days === 1 ? 'the day before' : `${days} days before`;
    let text = `Employees can order ${this.selectedSessionName} up to ${MealSessionFormComponent.to12Hour(v.orderCutoffTime)} ${when}.`;

    const start = MealSessionFormComponent.toMinutes(v.startTime);
    if (start !== null && !this.cutoffConflict) {
      text += ` That is ${MealSessionFormComponent.formatLead(days * 1440 + (start - cutoff))} before it is served at ${v.startTime}.`;
    }
    return `${text} After that the count is final - the meal can no longer be ordered or cancelled.`;
  }

  /// Empty unless the deadline is unreachable: a same-day cutoff later than the meal's own start time.
  get cutoffConflict(): string {
    const v = this.mealSessionForm.getRawValue();
    if (Number(v.orderCutoffDaysBefore ?? 0) !== 0) return '';

    const cutoff = MealSessionFormComponent.toMinutes(v.orderCutoffTime);
    const start = MealSessionFormComponent.toMinutes(v.startTime);
    if (cutoff === null || start === null || cutoff <= start) return '';

    return `Orders would close at ${v.orderCutoffTime}, after ${this.selectedSessionName} starts at ${v.startTime}. Choose an earlier time, or move the deadline to a day before the meal.`;
  }

  private get selectedSessionName(): string {
    const id = Number(this.mealSessionForm.getRawValue().sessionNameId ?? 0);
    return this.sessionNames.find((x) => x.id === id)?.name ?? 'this meal';
  }

